  [
    {
      "fieldName": "ucinn_ascendv2__Relationship_Map_Display_Name__c",
      "toolTip": "Name to be displayed on the UI for this relationship map configuration.",
      "required": true,
      "customFieldParams": {
        "type": "text",
        "label": "Relationship Map Display Name"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Host_Object_Name__c",
      "toolTip": "The object that would be hosting the relationship map. (I.E. Contact)",
      "customFieldParams": {
        "type": "text",
        "label": "Host Object Name"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Initial_Render_Method__c",
      "toolTip": "Determines how the relationship map initially renders to the user.\n1: Renders the source node only.\n2: Renders up to Initial Render Depth by default, with at most Max Nodes To Render nodes.\n3: Renders all levels up to Max Nodes To Render nodes.",
      "customFieldParams": {
        "type": "picklist",
        "label": "Initial Render Method",
        "customPicklistValuesString": [
          "Method 1 - Level 0 Only",
          "Method 2 - Initial Render Depth",
          "Method 3 - Max Nodes to Render"
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Initial_Render_Depth__c",
      "toolTip": "This value determines the initial relationship depth to render when the relationship map is invoked. This assumes that the # of nodes rendered with just Level 1 does not exceed the Max Nodes to Render value.",
      "customFieldParams": {
        "type": "number",
        "label": "Initial Render Depth"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Target_Depth_Level__c",
      "toolTip": "Maximum Depth Level of relationships to query, where the source is level 0.",
      "required": true,
      "customFieldParams": {
        "type": "number",
        "label": "Maximum Depth Level"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Inferred_Max_Search_Depth__c",
      "customFieldParams": {
        "type": "number",
        "label": "Inferred Max Search Depth"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Max_Nodes_To_Render__c",
      "toolTip": "This value determines the maximum number of relationships that the relationship will render before a filter is required. It does not limit the depth of the map to render.",
      "customFieldParams": {
        "type": "number",
        "label": "Max Nodes To Render"
      }
    },
    {
      "fieldName": "BLANK_Max_Nodes_To_Rende"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Description__c",
